//! NVENC FFI — bindings are **generated by bindgen** from the vendored
//! `nvEncodeAPI.h` (see `build.rs`), so every struct layout/size matches the SDK
//! header exactly. This module re-exports them and adds a few small helpers that
//! bindgen does not provide (version packing, status names).
//!
//! Windows-only (the crate's Windows code is `#[cfg(windows)]`).

#![allow(non_snake_case, non_camel_case_types, non_upper_case_globals, dead_code)]

// Pull in the generated bindings (structs, enums, GUID constants, fn-pointer table,
// NvEncodeAPICreateInstance / NvEncodeAPIGetMaxSupportedVersion typedefs).
include!(concat!(env!("OUT_DIR"), "/nvenc_bindings.rs"));

use std::os::raw::c_int;

pub type NVENCSTATUS_T = c_int;
pub const NV_ENC_SUCCESS_I: NVENCSTATUS_T = 0;
pub const NV_ENC_ERR_NEED_MORE_INPUT_I: NVENCSTATUS_T = 20;

/// Human-readable NVENC status name (numeric codes are easy to misread).
pub fn status_name(st: i32) -> &'static str {
    match st {
        0 => "SUCCESS",
        1 => "NO_ENCODE_DEVICE",
        2 => "UNSUPPORTED_DEVICE",
        3 => "INVALID_ENCODERDEVICE",
        4 => "INVALID_DEVICE",
        5 => "DEVICE_NOT_EXIST",
        6 => "INVALID_PTR",
        7 => "INVALID_EVENT",
        8 => "INVALID_PARAM",
        9 => "INVALID_CALL",
        10 => "OUT_OF_MEMORY",
        11 => "ENCODER_NOT_INITIALIZED",
        12 => "UNSUPPORTED_PARAM",
        13 => "LOCK_BUSY",
        14 => "NOT_ENOUGH_BUFFER",
        15 => "INVALID_VERSION",
        16 => "MAP_FAILED",
        20 => "NEED_MORE_INPUT",
        21 => "ENCODER_BUSY",
        _ => "UNKNOWN",
    }
}

/// SDK API version. The header defines NVENCAPI_MAJOR/MINOR_VERSION as macros, which
/// bindgen does NOT emit, so we provide the version packing here. Overridable at
/// runtime via env for driver-version flexibility.
pub const NVENCAPI_MAJOR_FALLBACK: u32 = 13;
pub const NVENCAPI_MINOR_FALLBACK: u32 = 0;

pub fn api_version() -> u32 {
    let major = std::env::var("G9_NVENC_MAJOR")
        .ok()
        .and_then(|s| s.parse::<u32>().ok())
        .unwrap_or(NVENCAPI_MAJOR_FALLBACK);
    let minor = std::env::var("G9_NVENC_MINOR")
        .ok()
        .and_then(|s| s.parse::<u32>().ok())
        .unwrap_or(NVENCAPI_MINOR_FALLBACK);
    major | (minor << 24)
}

/// NVENCAPI_STRUCT_VERSION(ver) = api_version | (ver<<16) | (0x7<<28)
pub fn struct_version(ver: u32) -> u32 {
    api_version() | (ver << 16) | (0x7 << 28)
}

// --- Clean aliases for the enum constants bindgen emits with a leading underscore
// --- (the C enum tag is `_NV_ENC_*`, so its constants inherit that prefix). These
// --- let nvenc.rs read naturally and keep the exact values in one place.
pub const NV_ENC_DEVICE_TYPE_DIRECTX: _NV_ENC_DEVICE_TYPE =
    _NV_ENC_DEVICE_TYPE_NV_ENC_DEVICE_TYPE_DIRECTX;
pub const NV_ENC_PARAMS_RC_CBR: _NV_ENC_PARAMS_RC_MODE =
    _NV_ENC_PARAMS_RC_MODE_NV_ENC_PARAMS_RC_CBR;
pub const NV_ENC_PARAMS_RC_VBR: _NV_ENC_PARAMS_RC_MODE =
    _NV_ENC_PARAMS_RC_MODE_NV_ENC_PARAMS_RC_VBR;
pub const NV_ENC_INPUT_RESOURCE_TYPE_DIRECTX: _NV_ENC_INPUT_RESOURCE_TYPE =
    _NV_ENC_INPUT_RESOURCE_TYPE_NV_ENC_INPUT_RESOURCE_TYPE_DIRECTX;
pub const NV_ENC_BUFFER_FORMAT_NV12: _NV_ENC_BUFFER_FORMAT =
    _NV_ENC_BUFFER_FORMAT_NV_ENC_BUFFER_FORMAT_NV12;
pub const NV_ENC_PIC_STRUCT_FRAME: _NV_ENC_PIC_STRUCT =
    _NV_ENC_PIC_STRUCT_NV_ENC_PIC_STRUCT_FRAME;
pub const NV_ENC_PIC_FLAG_FORCEIDR: _NV_ENC_PIC_FLAGS =
    _NV_ENC_PIC_FLAGS_NV_ENC_PIC_FLAG_FORCEIDR;
pub const NV_ENC_PIC_FLAG_OUTPUT_SPSPPS: _NV_ENC_PIC_FLAGS =
    _NV_ENC_PIC_FLAGS_NV_ENC_PIC_FLAG_OUTPUT_SPSPPS;
pub const NV_ENC_TUNING_INFO_LOW_LATENCY: _NV_ENC_TUNING_INFO =
    _NV_ENC_TUNING_INFO_NV_ENC_TUNING_INFO_LOW_LATENCY;
pub const NV_ENC_TUNING_INFO_ULTRA_LOW_LATENCY: _NV_ENC_TUNING_INFO =
    _NV_ENC_TUNING_INFO_NV_ENC_TUNING_INFO_ULTRA_LOW_LATENCY;
pub const NV_ENC_TUNING_INFO_HIGH_QUALITY: _NV_ENC_TUNING_INFO =
    _NV_ENC_TUNING_INFO_NV_ENC_TUNING_INFO_HIGH_QUALITY;
